import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
const trans = (key, params) => app.translator.trans(`ramon-verified.admin.requests.${key}`, params ?? {});
const IMAGE_EXTS = ['png', 'jpg', 'jpeg', 'webp', 'gif'];
function detectExtension(url, filename) {
  const candidate = filename || url || '';
  const stripped = String(candidate).split('?')[0].split('#')[0];
  const dotIdx = stripped.lastIndexOf('.');
  if (dotIdx === -1) return '';
  return stripped.slice(dotIdx + 1).toLowerCase();
}

/**
 * Inline preview for a verification document (image or PDF). Replaces the
 * old "open in new tab" link with a contained modal so reviewing happens
 * in-place without context-switching the admin's tabs.
 */
export default class DocumentPreviewModal extends Modal {
  imageLoaded = false;
  imageError = false;
  className() {
    return 'DocumentPreviewModal';
  }
  title() {
    return trans('document_preview_title');
  }
  content() {
    const {
      url,
      filename,
      typeLabel
    } = this.attrs;
    const ext = detectExtension(url, filename);
    const isImage = IMAGE_EXTS.indexOf(ext) !== -1;
    const isPdf = ext === 'pdf';
    return m("div", {
      className: "Modal-body DocumentPreviewModal-body"
    }, typeLabel ? m("div", {
      className: "DocumentPreviewModal-meta"
    }, m("span", {
      className: "DocumentPreviewModal-meta-label"
    }, trans('document_label')), m("span", {
      className: "DocumentPreviewModal-meta-value"
    }, typeLabel)) : null, m("div", {
      className: 'DocumentPreviewModal-frame' + (isPdf ? ' DocumentPreviewModal-frame--pdf' : '')
    }, isImage ? this.renderImage(url) : null, isPdf ? this.renderPdf(url) : null, !isImage && !isPdf ? this.renderUnsupported() : null));
  }
  renderImage(url) {
    return [!this.imageLoaded && !this.imageError ? m("div", {
      className: "DocumentPreviewModal-loading"
    }, m(LoadingIndicator, null)) : null, this.imageError ? m("div", {
      className: "DocumentPreviewModal-empty"
    }, m("i", {
      className: "icon fas fa-triangle-exclamation"
    }), m("span", null, trans('preview_failed'))) : m("img", {
      src: url,
      alt: "",
      className: 'DocumentPreviewModal-img' + (this.imageLoaded ? ' is-loaded' : ''),
      onload: () => {
        this.imageLoaded = true;
        m.redraw();
      },
      onerror: () => {
        this.imageError = true;
        m.redraw();
      }
    })];
  }
  renderPdf(url) {
    return m("iframe", {
      src: url,
      className: "DocumentPreviewModal-pdf",
      title: typeof trans('document_preview_title') === 'string' ? trans('document_preview_title') : 'Document preview'
    });
  }
  renderUnsupported() {
    return m("div", {
      className: "DocumentPreviewModal-empty"
    }, m("i", {
      className: "icon fas fa-file"
    }), m("span", null, trans('preview_unavailable')));
  }
}
flarum.reg.add('ramon-verified', 'admin/components/DocumentPreviewModal', DocumentPreviewModal);